def deg_below(r):   # 1..99 مع «درجة» (مؤنّثة)
    if r==1: return 'دَرَجَةٌ وَاحِدَةٌ'
    if r==2: return 'دَرَجَتَانِ'
    if r<=10: return FF[r]+' دَرَجَاتٍ'
    if r<20: return FT[r]+' دَرَجَةً'
    u,t=r%10,r-r%10
    return (F1[u]+' وَ' if u else '')+TN[t]+' دَرَجَةً'
def degphrase(n):
    h,r=divmod(n,100)
    if not h: return deg_below(r)
    if not r: return HC[h]+' دَرَجَةٍ'
    return HN[h]+' وَ'+deg_below(r)
# ألعاب U6 الحركية (D288 (2)): نظير make في 49_m4_g_circ4b.js
def chordg(r,L=None,d0=0,q=None,rot=0):
    it={"t":"c6ChordGame","r":r,"d0":d0}
    if rot: it["rot"]=rot
    if L is not None: d=math.isqrt(r*r-L*L//4); assert d*d*4==4*r*r-L*L, (r,L); it["L"]=L
    if q: it["q"]=q
    return it
def tang(mode,a=None,op=None,q=None,r=6,noAng=False):
    it={"t":"c6TanGame","mode":mode}
    if a is not None: it["a"]=a
    if r!=6: it["r"]=r
    if noAng: it["noAng"]=True
    if op is not None: l=math.isqrt(op*op-r*r); assert l*l==op*op-r*r, op; it["op"]=op
    else: DEGS.update([90,180,45,60])
    if q: it["q"]=q
    return it
def ceng(cen,pAt=None,q=None,rot=0):
    i=cen//2; assert cen%20==0 and 180-cen not in (i,) , cen   # قراءاتٌ على التدريج، والمشتّتان مختلفان
    DEGS.update(v for v in [cen,180-cen,i,cen-20,180-i,i//2] if 0<v<=360)
    it={"t":"c6CenGame","cen":cen}
    if rot: it["rot"]=rot
    if pAt is not None: it["pAt"]=pAt
    if q: it["q"]=q
    return it
def ang(cen,ask,pAt=None):
    i=cen//2; DEGS.update(v for v in [cen, i, 180-i, min(2*cen,360), 90+i, 360-cen, 180-cen, 45] if 0<v<=360); d={"t":"ci4Ang","cen":cen,"ask":ask,"q":"gen.ci4.q.ang."+ask}
    if pAt is not None: d["pAt"]=pAt
    return d
