L2={
 "bag.ask":"هَلْ {مَعَكَ|مَعَكِ} فِرْجَارٌ وَمِسْطَرَةٌ؟ أَمْ نَعْمَلُ عَلَى الشَّاشَةِ؟",
 "hk.01":["chaos","هَذَا المُسْتَقِيمُ مُمَاسٌّ، لِأَنَّهُ يَلْمِسُ الدَّائِرَةَ مِنْ جِهَتَيْنِ!"],
 "hk.02":"كَمْ نُقْطَةً مُشْتَرَكَةً بَيْنَهُ وَبَيْنَ الدَّائِرَةِ؟",
 "tn.01":"نُزْلِقُ المِسْطَرَةَ: نُقْطَتَانِ، ثُمَّ نُقْطَةٌ وَاحِدَةٌ فَقَطْ، ثُمَّ لَا شَيْءَ. المُسْتَقِيمُ الَّذِي يَلْمِسُ الدَّائِرَةَ فِي نُقْطَةٍ وَاحِدَةٍ مُمَاسٌّ، وَهِيَ نُقْطَةُ التَّمَاسِّ.",
 "tn.02":"نَرْسُمُ نِصْفَ القُطْرِ إِلَى نُقْطَةِ التَّمَاسِّ، وَنَضَعُ عَلَيْهِ وَرَقَةَ الزَّاوِيَةِ القَائِمَةِ: المُمَاسُّ عَمُودِيٌّ عَلَيْهِ.",
 "tn.03":"وَلِمَاذَا؟ لَوْ لَمْ يَكُنْ عَمُودِيًّا، لَكَانَتْ عَلَى المُمَاسِّ نُقْطَةٌ أَقْرَبُ إِلَى المَرْكَزِ، لِأَنَّ العَمُودَ أَقْصَرُ مَسَافَةٍ. فَتَكُونُ دَاخِلَ الدَّائِرَةِ، فَيَقْطَعُهَا المُسْتَقِيمُ فِي نُقْطَتَيْنِ، وَهَذَا لَيْسَ مُمَاسًّا.",
 "tn.04":"القَاعِدَةُ: المُمَاسُّ يَلْمِسُ الدَّائِرَةَ فِي نُقْطَةٍ وَاحِدَةٍ، وَهُوَ عَمُودِيٌّ عَلَى نِصْفِ القُطْرِ عِنْدَهَا.",
 "tt.01":"وَمِنْ نُقْطَةٍ خَارِجَ الدَّائِرَةِ نَرْسُمُ مُمَاسَّيْنِ.",
 "tt.02":"نَقِيسُهُمَا: طُولَاهُمَا مُتَسَاوِيَانِ.",
 "mat.01":"{اُرْسُمْ|اُرْسُمِي} بِالفِرْجَارِ دَائِرَةً، {وَضَعِ|وَضَعِي} المِسْطَرَةَ عَلَيْهَا حَتَّى تَلْمِسَهَا فِي نُقْطَةٍ وَاحِدَةٍ، {وَارْسُمْ|وَارْسُمِي} نِصْفَ القُطْرِ إِلَيْهَا. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "mat.02":"وَالآنَ عَلَى الشَّاشَةِ.",
 "gm.intro":"لُعْبَةُ «المِسْطَرَةِ وَالدَّائِرَةِ»: {حَرِّكِ|حَرِّكِي} المِسْطَرَةَ حَتَّى تَلْمِسَ الدَّائِرَةَ فِي نُقْطَةٍ وَاحِدَةٍ، ثُمَّ {اِفْحَصِ|اِفْحَصِي} الزَّاوِيَةَ عِنْدَ نُقْطَةِ التَّمَاسِّ.",
 "tg.01":"مِسْطَرَةٌ تَقْطَعُ الدَّائِرَةَ: {أَبْعِدْهَا|أَبْعِدِيهَا} حَتَّى تَلْمِسَهَا فِي نُقْطَةٍ وَاحِدَةٍ، ثُمَّ «تَمَّ».",
 "tg.02":"وَمِسْطَرَةٌ مَائِلَةٌ: {حَرِّكْهَا|حَرِّكِيهَا} حَتَّى تَصِيرَ مُمَاسًّا.",
 "tg.03":"وَمِسْطَرَةٌ تَدُورُ حَوْلَ نُقْطَةٍ خَارِجَ الدَّائِرَةِ: {أَدِرْهَا|أَدِيرِيهَا} حَتَّى تَصِيرَ مُمَاسًّا.",
 "gm.end":"{أَحْسَنْتَ|أَحْسَنْتِ}: المُمَاسُّ يَلْمِسُ الدَّائِرَةَ فِي نُقْطَةٍ وَاحِدَةٍ، وَهُوَ عَمُودِيٌّ عَلَى نِصْفِ القُطْرِ عِنْدَهَا.",
 "pr.intro":"نَتَدَرَّبُ.",
 "pr.r1":"قَالَتْ فَوْضَى: المُمَاسُّ يَقْطَعُ الدَّائِرَةَ فِي نُقْطَتَيْنِ. مَا خَطَؤُهَا؟",
 "pr.r1a":"المُمَاسُّ يَلْمِسُهَا فِي نُقْطَةٍ وَاحِدَةٍ، وَمَا يَقْطَعُهَا فِي نُقْطَتَيْنِ لَيْسَ مُمَاسًّا.",
 "pr.r1b":"لَا خَطَأَ: المُسْتَقِيمُ الَّذِي يَقْطَعُ الدَّائِرَةَ فِي نُقْطَتَيْنِ مُمَاسٌّ لَهَا.",
 "pr.r1c":"المُمَاسُّ لَا يَلْمِسُ الدَّائِرَةَ، بَلْ يَمُرُّ قَرِيبًا مِنْهَا جِدًّا.",
 "pr.r2":"لِمَاذَا المُمَاسُّ عَمُودِيٌّ عَلَى نِصْفِ القُطْرِ عِنْدَ نُقْطَةِ التَّمَاسِّ؟",
 "pr.r2a":"لَوْ لَمْ يَكُنْ، لَكَانَتْ عَلَيْهِ نُقْطَةٌ دَاخِلَ الدَّائِرَةِ فَيَقْطَعُهَا.",
 "pr.r2b":"نِصْفُ القُطْرِ أَطْوَلُ مِنَ المُمَاسِّ، فَيَلْتَقِيَانِ بِزَاوِيَةٍ قَائِمَةٍ.",
 "pr.r2c":"قِسْنَا الزَّاوِيَةَ بِالمِنْقَلَةِ مَرَّةً فِي رَسْمٍ وَاحِدٍ فَوَجَدْنَاهَا قَائِمَةً.",
 "ch.find":"قَالَتْ فَوْضَى: هَذَا المُسْتَقِيمُ يَلْمِسُ الدَّائِرَةَ مِنْ جِهَتَيْنِ، فَهُوَ مُمَاسٌّ. هَلْ هُوَ مُمَاسٌّ؟",
 "ch.after":["chaos","آه! المُمَاسُّ نُقْطَةٌ وَاحِدَةٌ فَقَطْ."],
 "ch.right":"يَقْطَعُهَا فِي نُقْطَتَيْنِ، فَلَيْسَ مُمَاسًّا.",
 "ch.wrong":["chaos","كُلَّمَا لَمَسَ أَكْثَرَ كَانَ أَفْضَلَ."],
 "ms.1":"كَيْفَ نَعْرِفُ أَنَّ المُسْتَقِيمَ مُمَاسٌّ لِلدَّائِرَةِ؟",
 "ms.1a":"نَصِلُ المَرْكَزَ بِنُقْطَةِ اللِّقَاءِ: إِنْ عَامَدَ المُسْتَقِيمَ فَهُوَ مُمَاسٌّ.",
 "ms.1b":"هُوَ قَرِيبٌ جِدًّا مِنَ الدَّائِرَةِ، وَيَمُرُّ خَارِجَهَا كُلَّهُ دُونَ أَنْ يَلْمِسَهَا.",
 "ms.1c":"يَمُرُّ بِمَرْكَزِ الدَّائِرَةِ، وَيَقْطَعُهَا فِي نُقْطَتَيْنِ مُتَقَابِلَتَيْنِ.",
 "ms.x1":"عَجَلَةُ دَرَّاجَةٍ عَلَى أَرْضٍ مُسْتَوِيَةٍ تَلْمِسُهَا فِي نُقْطَةٍ وَاحِدَةٍ. لِمَاذَا نِصْفُ القُطْرِ إِلَى تِلْكَ النُّقْطَةِ عَمُودِيٌّ عَلَى الأَرْضِ؟",
 "ms.x1a":"لِأَنَّ الأَرْضَ مُمَاسٌّ لِلْعَجَلَةِ، وَالمُمَاسُّ عَمُودِيٌّ عَلَى نِصْفِ القُطْرِ عِنْدَ التَّمَاسِّ.",
 "ms.x1b":"لِأَنَّ نِصْفَ القُطْرِ أَطْوَلُ قِطْعَةٍ فِي العَجَلَةِ، فَيَقِفُ عَمُودِيًّا عَلَى الأَرْضِ.",
 "ms.x1c":"لِأَنَّ العَجَلَةَ تَقْطَعُ الأَرْضَ فِي نُقْطَتَيْنِ قَرِيبَتَيْنِ جِدًّا، وَالعَمُودُ يَمُرُّ بَيْنَهُمَا.",
 "ms.recall":"نَتَذَكَّرُ: نَعُدُّ النُّقَطَ المُشْتَرَكَةَ، وَنَرْسُمُ نِصْفَ القُطْرِ إِلَى نُقْطَةِ التَّمَاسِّ وَنَقِيسُ زَاوِيَتَهُ، فَنَحْسُبُ بِفِيثَاغُورْسَ.",
 "ms.ok":"{أَتْقَنْتَ|أَتْقَنْتِ} المُمَاسَّ!",
 "wrap.01":"المُمَاسُّ نُقْطَةٌ وَاحِدَةٌ وَزَاوِيَةٌ قَائِمَةٌ!",
 "wrap.home":["chaos","مُهِمَّةُ البَيْتِ: {ضَعْ|ضَعِي} طَبَقًا مُسْتَدِيرًا عَلَى الطَّاوِلَةِ، {وَثَبِّتْ|وَثَبِّتِي} عِنْدَ حَافَّتِهِ مِسْطَرَةً تَلْمِسُهُ فِي نُقْطَةٍ وَاحِدَةٍ، {وَتَحَقَّقْ|وَتَحَقَّقِي} مَعَ {أَهْلِكَ|أَهْلِكِ} مِنَ الزَّاوِيَةِ القَائِمَةِ."],
}
