# ---------------- د3: الزوايا المحيطية (C412) ----------------
L3={
 "bag.ask":"هَلْ {مَعَكَ|مَعَكِ} فِرْجَارٌ وَمِنْقَلَةٌ؟ أَمْ نَعْمَلُ عَلَى الشَّاشَةِ؟",
 "hk.01":["chaos","الزَّاوِيَةُ المُحِيطِيَّةُ تُسَاوِي المَرْكَزِيَّةَ عَلَى القَوْسِ نَفْسِهِ!"],
 "hk.02":"المَرْكَزِيَّةُ رَأْسُهَا المَرْكَزُ. نَقِيسُهَا: ثَمَانُونَ دَرَجَةً.",
 "hk.03":"وَالمُحِيطِيَّةُ رَأْسُهَا عَلَى الدَّائِرَةِ، وَضِلْعَاهَا وَتَرَانِ. نَقِيسُهَا: أَرْبَعُونَ دَرَجَةً. {قَارِنْ|قَارِنِي}: هَلْ تَتَسَاوَيَانِ؟",
 "in.01":"قَوْسٌ آخَرُ مَرْكَزِيَّتُهُ مِئَةُ دَرَجَةٍ، وَالمُحِيطِيَّةُ عَلَيْهِ خَمْسُونَ.",
 "in.02":"نُحَرِّكُ رَأْسَ المُحِيطِيَّةِ عَلَى الدَّائِرَةِ: تَبْقَى خَمْسِينَ مَا دَامَ القَوْسُ نَفْسَهُ.",
 "in.03":"وَإِذَا كَانَ القَوْسُ نِصْفَ دَائِرَةٍ، فَالمَرْكَزِيَّةُ مِئَةٌ وَثَمَانُونَ، وَالمُحِيطِيَّةُ عَلَى القُطْرِ قَائِمَةٌ.",
 "in.04":"القَاعِدَةُ: الزَّاوِيَةُ المُحِيطِيَّةُ نِصْفُ المَرْكَزِيَّةِ المُقَابِلَةِ لِلْقَوْسِ نَفْسِهِ.",
 "pp.00":"وَلِمَاذَا النِّصْفُ؟ نُبَرْهِنُ حِينَ يَمُرُّ ضِلْعُ المُحِيطِيَّةِ بِالمَرْكَزِ.",
 "pp.01":"مِيمْ نُونْ يُسَاوِي مِيمْ أَلِفْ، لِأَنَّهُمَا نِصْفَا قُطْرٍ: المُثَلَّثُ مُتَسَاوِي السَّاقَيْنِ.",
 "pp.02":"فَزَاوِيَتَا قَاعِدَتِهِ عِنْدَ نُونْ وَأَلِفْ مُتَسَاوِيَتَانِ.",
 "pp.03":"وَالمَرْكَزِيَّةُ زَاوِيَةٌ خَارِجِيَّةٌ لِلْمُثَلَّثِ، فَتُسَاوِي مَجْمُوعَهُمَا: ضِعْفَ المُحِيطِيَّةِ.",
 "pp.04":"وَالحَالَتَانِ الأُخْرَيَانِ تَعُودَانِ إِلَى هَذِهِ بِقُطْرٍ مُسَاعِدٍ.",
 "mat.01":"{اُرْسُمْ|اُرْسُمِي} بِالفِرْجَارِ دَائِرَةً، {وَارْسُمْ|وَارْسُمِي} زَاوِيَةً مَرْكَزِيَّةً وَمُحِيطِيَّةً عَلَى القَوْسِ نَفْسِهِ، {وَقِسْهُمَا|وَقِيسِيهِمَا} بِالمِنْقَلَةِ. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "mat.02":"وَالآنَ عَلَى الشَّاشَةِ.",
 "gm.intro":"لُعْبَةُ «أَيْنَ المَرْكَزُ؟»: {اِلْمِسِ|اِلْمِسِي} المَرْكَزَ، ثُمَّ {قِسِ|قِيسِي} الزَّاوِيَتَيْنِ بِالمِنْقَلَةِ.",
 "cn.01":"زَاوِيَةٌ مُحِيطِيَّةٌ عَلَى قَوْسٍ أَحْمَرَ. أَيْنَ مَرْكَزُ الدَّائِرَةِ؟ {اِلْمِسْهُ|اِلْمِسِيهِ}.",
 "cn.02":"وَزَاوِيَةٌ أُخْرَى رَأْسُهَا فِي مَكَانٍ آخَرَ. أَيْنَ المَرْكَزُ؟",
 "cn.03":"وَقَوْسٌ آخَرُ. أَيْنَ المَرْكَزُ؟",
 "gm.end":"{أَحْسَنْتَ|أَحْسَنْتِ}: المُحِيطِيَّةُ نِصْفُ المَرْكَزِيَّةِ عَلَى القَوْسِ نَفْسِهِ.",
 "pr.intro":"نَتَدَرَّبُ.",
 "pr.r2":"قَالَتْ فَوْضَى: الزَّاوِيَةُ المُحِيطِيَّةُ عَلَى القُطْرِ قَائِمَةٌ. مَا خَطَؤُهَا؟",
 "pr.r2a":"لَا خَطَأَ: مَرْكَزِيَّتُهَا مِئَةٌ وَثَمَانُونَ، وَهِيَ نِصْفُهَا: تِسْعُونَ.",
 "pr.r2b":"هِيَ مِئَةٌ وَثَمَانُونَ دَرَجَةً، مِثْلُ القُطْرِ المُسْتَقِيمِ نَفْسِهِ.",
 "pr.r2c":"تَكُونُ قَائِمَةً حِينَ يَكُونُ رَأْسُهَا فِي أَعْلَى الدَّائِرَةِ.",
 "pr.r1":"قَالَتْ فَوْضَى: الزَّاوِيَةُ المُحِيطِيَّةُ تُسَاوِي المَرْكَزِيَّةَ دَائِمًا. مَا خَطَؤُهَا؟",
 "pr.r1a":"المُحِيطِيَّةُ نِصْفُ المَرْكَزِيَّةِ عَلَى القَوْسِ نَفْسِهِ، لَا مِثْلُهَا.",
 "pr.r1b":"لَا خَطَأَ: الزَّاوِيَتَانِ تُقَابِلَانِ القَوْسَ نَفْسَهُ فَهُمَا مُتَسَاوِيَتَانِ.",
 "pr.r1c":"المُحِيطِيَّةُ ضِعْفُ المَرْكَزِيَّةِ، فَرَأْسُهَا أَبْعَدُ عَنِ القَوْسِ.",
 "ch.find":"قَالَتْ فَوْضَى: المُحِيطِيَّةُ هُنَا مِئَةٌ وَعِشْرُونَ مِثْلُ المَرْكَزِيَّةِ. كَمْ هِيَ حَقًّا؟",
 "ch.after":["chaos","آه! المُحِيطِيَّةُ نِصْفُ المَرْكَزِيَّةِ."],
 "ch.right":"نَقْسِمُ المَرْكَزِيَّةَ عَلَى اثْنَيْنِ.",
 "ch.wrong":["chaos","القَوْسُ نَفْسُهُ، فَالزَّاوِيَةُ نَفْسُهَا."],
 "ms.1":"لِمَاذَا الزَّاوِيَةُ المُحِيطِيَّةُ عَلَى القُطْرِ قَائِمَةٌ؟",
 "ms.1a":"مَرْكَزِيَّةُ نِصْفِ الدَّائِرَةِ مُسْتَقِيمَةٌ، وَالمُحِيطِيَّةُ نِصْفُهَا.",
 "ms.1b":"القُطْرُ أَطْوَلُ الأَوْتَارِ، فَيَصْنَعُ أَكْبَرَ زَاوِيَةٍ مُمْكِنَةٍ عَلَيْهِ.",
 "ms.1c":"ضِلْعَاهَا يَقْطَعَانِ الدَّائِرَةَ فِي نُقْطَتَيْنِ مُتَقَابِلَتَيْنِ عَلَيْهَا.",
 "ms.x1":"نُقْطَتَانِ عَلَى دَائِرَةٍ، وَرَأْسُ زَاوِيَةٍ مُحِيطِيَّةٍ يَتَحَرَّكُ عَلَى القَوْسِ الآخَرِ. لِمَاذَا لَا يَتَغَيَّرُ قِيَاسُهَا؟",
 "ms.x1a":"لِأَنَّهَا نِصْفُ المَرْكَزِيَّةِ عَلَى القَوْسِ نَفْسِهِ، وَالمَرْكَزِيَّةُ لَا تَتَغَيَّرُ.",
 "ms.x1b":"لِأَنَّ ضِلْعَيْهَا يَطُولَانِ مَعًا حِينَ يَتَحَرَّكُ رَأْسُهَا، فَتَبْقَى الزَّاوِيَةُ كَمَا هِيَ.",
 "ms.x1c":"لِأَنَّ الزَّاوِيَةَ الَّتِي رَأْسُهَا عَلَى الدَّائِرَةِ قَائِمَةٌ، وَالقَوْسُ لَا يُغَيِّرُهَا.",
 "ms.recall":"نَتَذَكَّرُ: نَجِدُ القَوْسَ الَّذِي تَقِفُ عَلَيْهِ الزَّاوِيَةُ، ثُمَّ المَرْكَزِيَّةَ عَلَيْهِ، وَنُقَارِنُ بَيْنَهُمَا.",
 "ms.ok":"{أَتْقَنْتَ|أَتْقَنْتِ} الزَّوَايَا المُحِيطِيَّةَ!",
 "wrap.01":"المُحِيطِيَّةُ نِصْفُ المَرْكَزِيَّةِ!",
 "wrap.home":["chaos","مُهِمَّةُ البَيْتِ: {اُرْسُمْ|اُرْسُمِي} دَائِرَةً فِيهَا قُطْرٌ، {وَارْسُمْ|وَارْسُمِي} زَوَايَا رُؤُوسُهَا عَلَى الدَّائِرَةِ وَضِلْعَاهَا إِلَى طَرَفَيِ القُطْرِ، {وَقِسْهَا|وَقِيسِيهَا} مَعَ {أَهْلِكَ|أَهْلِكِ}."],
}
