L4={
 "bag.ask":"هَلْ {مَعَكَ|مَعَكِ} خَيْطٌ وَمِسْطَرَةٌ؟ أَمْ نَعْمَلُ عَلَى الشَّاشَةِ؟",
 "ar.00":["chaos","طُولُ القَوْسِ نِصْفُ مُحِيطِ الدَّائِرَةِ دَائِمًا!"],
 "ar.01":"هَذَا القَوْسُ رُبْعُ الدَّائِرَةِ: تِسْعُونَ دَرَجَةً مِنْ ثَلَاثِمِئَةٍ وَسِتِّينَ، فَطُولُهُ رُبْعُ المُحِيطِ.",
 "ar.02":"وَقَوْسُ مِئَةٍ وَثَمَانِينَ دَرَجَةً نِصْفُ المُحِيطِ.",
 "ar.03":"وَقَوْسُ ثَلَاثِمِئَةٍ وَسِتِّينَ المُحِيطُ كُلُّهُ.",
 "ar.04":"القَاعِدَةُ: طُولُ القَوْسِ هُوَ الزَّاوِيَةُ المَرْكَزِيَّةُ عَلَى ثَلَاثِمِئَةٍ وَسِتِّينَ، فِي مُحِيطِ الدَّائِرَةِ.",
 "se.01":"وَالقِطَاعُ جُزْءٌ مِنَ القُرْصِ بَيْنَ نِصْفَيْ قُطْرٍ وَقَوْسٍ.",
 "se.02":"مِسَاحَتُهُ بِالكَسْرِ نَفْسِهِ: قِطَاعُ تِسْعِينَ دَرَجَةً مِنْ قُرْصٍ مِسَاحَتُهُ مِئَةٌ، مِسَاحَتُهُ خَمْسَةٌ وَعِشْرُونَ.",
 "se.03":"القَاعِدَةُ: مِسَاحَةُ القِطَاعِ هِيَ الزَّاوِيَةُ عَلَى ثَلَاثِمِئَةٍ وَسِتِّينَ، فِي مِسَاحَةِ الدَّائِرَةِ.",
 "gd.01":"مَشْرُوعُ حَدِيقَةِ القَوْسِ: حَدِيقَةٌ مُسْتَدِيرَةٌ نِصْفُ قُطْرِهَا خَمْسَةُ أَمْتَارٍ.",
 "gd.04":"{اُحْسُبْ|اُحْسُبِي} {أَنْتَ|أَنْتِ}: طُولَ المَمَرِّ عَلَى قَوْسِ تِسْعِينَ دَرَجَةً، وَمِسَاحَةَ قِطَاعِ الزِّرَاعَةِ.",
 "tb.01":"جَدْوَلُ المَشْرُوعِ: مَا {حَسَبْتَهُ|حَسَبْتِهِ}: طُولُ المَمَرِّ بِالأَمْتَارِ، وَمِسَاحَةُ القِطَاعِ بِالأَمْتَارِ المُرَبَّعَةِ.",
 "tb.02":"وَلِلْإِبْدَاعِ: {صَمِّمْ|صَمِّمِي} حَدِيقَةً بِمَمَرٍّ عَلَى قَوْسٍ آخَرَ، {وَاحْسُبْ|وَاحْسُبِي} طُولَهُ وَمِسَاحَةَ قِطَاعِهِ.",
 "mat.01":"{مُدَّ|مُدِّي} خَيْطًا عَلَى حَافَّةِ طَبَقٍ مُسْتَدِيرٍ، {وَقِسْ|وَقِيسِي} بِالمِسْطَرَةِ رُبْعَهَا، {وَقَارِنْهُ|وَقَارِنِيهِ} بِرُبْعِ المُحِيطِ المَحْسُوبِ. ثُمَّ {اِلْمِسْ|اِلْمِسِي} «تَمَّ».",
 "mat.02":"وَالآنَ عَلَى الشَّاشَةِ.",
 "prj.intro":"نَحْسُبُ مَمَرَّاتِ الحَدَائِقِ وَقِطَاعَاتِهَا.",
 "pr.intro":"نَتَدَرَّبُ.",
 "pr.r1":"قَالَتْ فَوْضَى: طُولُ قَوْسِ تِسْعِينَ دَرَجَةً هُوَ تِسْعُونَ ضَرْبَ المُحِيطِ. مَا خَطَؤُهَا؟",
 "pr.r1a":"نَقْسِمُ الزَّاوِيَةَ عَلَى ثَلَاثِمِئَةٍ وَسِتِّينَ أَوَّلًا، فَالقَوْسُ رُبْعُ المُحِيطِ.",
 "pr.r1b":"لَا خَطَأَ: الدَّرَجَةُ الوَاحِدَةُ مِنَ الزَّاوِيَةِ تُضِيفُ مُحِيطًا كَامِلًا إِلَى طُولِ القَوْسِ.",
 "pr.r1c":"طُولُ القَوْسِ لَا يَتَعَلَّقُ بِالزَّاوِيَةِ، بَلْ بِطُولِ نِصْفِ القُطْرِ وَحْدَهُ.",
 "ch.find":"قَالَتْ فَوْضَى: هَذَا القَوْسُ نِصْفُ المُحِيطِ، فَكُلُّ قَوْسٍ نِصْفُ المُحِيطِ. كَمْ طُولُهُ حَقًّا؟",
 "ch.after":["chaos","آه! القَوْسُ كَسْرٌ مِنَ المُحِيطِ بِزَاوِيَتِهِ."],
 "ch.right":"الزَّاوِيَةُ رُبْعُ الدَّوْرَةِ، فَالقَوْسُ رُبْعُ المُحِيطِ.",
 "ch.wrong":["chaos","النِّصْفُ رَقْمٌ جَمِيلٌ."],
 "ms.1":"لِمَاذَا نَقْسِمُ الزَّاوِيَةَ عَلَى ثَلَاثِمِئَةٍ وَسِتِّينَ فِي طُولِ القَوْسِ؟",
 "ms.1a":"لِأَنَّ الدَّائِرَةَ كُلَّهَا ثَلَاثُمِئَةٍ وَسِتُّونَ دَرَجَةً، وَالقَوْسُ كَسْرٌ مِنْهَا.",
 "ms.1b":"لِأَنَّ المِنْقَلَةَ تُقَسِّمُ الزَّاوِيَةَ إِلَى ثَلَاثِمِئَةٍ وَسِتِّينَ جُزْءًا.",
 "ms.1c":"لِأَنَّ نِصْفَ القُطْرِ يَدُورُ حَوْلَ المَرْكَزِ ثَلَاثَمِئَةٍ وَسِتِّينَ مَرَّةً فِي الدَّوْرَةِ.",
 "ms.x1":"سَاعَةُ حَائِطٍ: عَقْرَبُ الدَّقَائِقِ يَدُورُ ثُلُثَ دَوْرَةٍ. لِمَاذَا يَقْطَعُ طَرَفُهُ ثُلُثَ مُحِيطِ الدَّائِرَةِ؟",
 "ms.x1a":"زَاوِيَتُهُ مِئَةٌ وَعِشْرُونَ مِنْ ثَلَاثِمِئَةٍ وَسِتِّينَ، فَالقَوْسُ الكَسْرُ نَفْسُهُ مِنَ المُحِيطِ.",
 "ms.x1b":"طُولُ العَقْرَبِ ثُلُثُ قُطْرِ السَّاعَةِ، فَيَقْطَعُ طَرَفُهُ ثُلُثَ مُحِيطِهَا كُلِّهِ فِي دَوْرَتِهِ.",
 "ms.x1c":"طَرَفُهُ يَقْطَعُ مِئَةً وَعِشْرِينَ سَنْتِيمِتْرًا مِنْ مُحِيطٍ طُولُهُ ثَلَاثُمِئَةٍ وَسِتُّونَ سَنْتِيمِتْرًا.",
 "ms.recall":"نَتَذَكَّرُ: نَسْأَلُ كَمْ شَرِيحَةً مِثْلَ القِطَاعِ تَمْلَأُ الدَّائِرَةَ، ثُمَّ نَأْخُذُ هَذَا الجُزْءَ مِنَ الكُلِّ.",
 "ms.ok":"{أَتْقَنْتَ|أَتْقَنْتِ} القَوْسَ وَالقِطَاعَ!",
 "wrap.01":"القَوْسُ كَسْرٌ مِنَ المُحِيطِ، وَالقِطَاعُ كَسْرٌ مِنَ القُرْصِ!",
 "wrap.home":["chaos","مُهِمَّةُ البَيْتِ: {قِسْ|قِيسِي} نِصْفَ قُطْرِ سَاعَةِ الحَائِطِ، {وَاحْسُبْ|وَاحْسُبِي} مُحِيطَهَا، ثُمَّ القَوْسَ مِنَ الاثْنَيْ عَشَرَ إِلَى الثَّلَاثَةِ وَمِنَ الاثْنَيْ عَشَرَ إِلَى الأَرْبَعَةِ، {وَقِسْهُمَا|وَقِيسِيهِمَا} بِخَيْطٍ يُمْسِكُهُ {أَهْلُكَ|أَهْلُكِ} مَشْدُودًا. ثُمَّ {اُرْسُمِ|اُرْسُمِي} الزَّاوِيَةَ بَيْنَ العَقْرَبَيْنِ عِنْدَ السَّاعَةِ الثَّالِثَةِ، {وَسَمِّهَا|وَسَمِّيهَا}: زَاوِيَةً مَرْكَزِيَّةً."],
}
